# Pseudocode for DBSCAN clustering
# Input: data matrix X, eps, minPts
# Output: cluster labels
for each point p in X:
    N = neighbours(p, eps)
    if |N| >= minPts:
        mark p as core
    else:
        mark p as noise
cluster_id = 0
for each core point p not yet assigned:
    cluster_id += 1
    expand_cluster(p, cluster_id)

function expand_cluster(p, cid):
    assign p to cid
    for each q in neighbours(p, eps):
        if q is noise: assign q to cid
        if q not assigned:
            assign q to cid
            if q is core: expand_cluster(q, cid)
